const $=id=>document.getElementById(id), c=$('canvas'),x=c.getContext('2d');let course='유형정리반',uploaded=null,busy=false;
const badges=new Image();badges.onload=()=>draw();badges.src="laurel-badges.png";
function text(t,a,b,size=30,color='#fff',weight=700,align='left'){x.fillStyle=color;x.font=`${weight} ${size}px "Noto Sans KR", sans-serif`;x.textAlign=align;x.fillText(t,a,b)}
function draw(){x.clearRect(0,0,1080,1080);x.fillStyle='#191e48';x.fillRect(0,0,1080,630);text('PAGODA',838,64,35,'#ec2028',900);text('서면',990,62,28,'#92929c');if(badges.complete&&badges.naturalWidth)x.drawImage(badges,25,10,373,157);
const headline=[['더쎈 ','#fff'],[course+' ','#ffcf36'],[$('period').value+' 수강 후 ','#fff'],[$('phrase').value.trim(),'#ffcf36']];
let headlineSize=43;const headlineWidth=()=>{x.font=`500 ${headlineSize}px "Noto Sans KR", sans-serif`;return headline.reduce((width,[label])=>width+x.measureText(label).width,0)};
while(headlineWidth()>940&&headlineSize>20)headlineSize--;
let headlineLeft=70;headline.forEach(([label,color])=>{text(label,headlineLeft,222,headlineSize,color,500);headlineLeft+=x.measureText(label).width});
[[70,530,180,100],[807,450,200,270]].forEach(([a,b,w,h])=>{x.strokeStyle='#75788f';x.lineWidth=3;x.beginPath();for(let i=0;i<3;i++){let xx=a+i*(w/3+4),yy=b-i*h/3;x.fillStyle='#2d3257';x.fillRect(xx,yy,w/3-7,558-yy);if(!i)x.moveTo(xx+24,yy-12);else x.lineTo(xx+24,yy-12)}x.stroke();for(let i=0;i<3;i++){x.beginPath();x.fillStyle='#f01c24';x.arc(a+i*(w/3+4)+24,b-i*h/3-12,6,0,Math.PI*2);x.fill()}});
x.save();x.transform(1,0,-.13,1,43,0);text(`${$('score').value||0}점 달성!`,540,390,128,'white',900,'center');text('더쎈하자',568,550,140,'#f01820',900,'center');x.restore();
x.fillStyle='#fff';x.fillRect(0,630,1080,450);
if($('evidence').value==='image'&&uploaded){x.strokeStyle='#ef1c23';x.lineWidth=12;x.strokeRect(102,662,876,236);let scale=Math.min(852/uploaded.width,212/uploaded.height);x.drawImage(uploaded,114+(852-uploaded.width*scale)/2,674+(212-uploaded.height*scale)/2,uploaded.width*scale,uploaded.height*scale)}else{text('TOEIC SCORE',540,714,22,'#9396a7',700,'center');text(($('score').value||0)+'점',540,830,104,'#191e48',900,'center');text(course+' · '+$('period').value+' 수강',540,878,26,'#74788c',500,'center')}
let name=$('name').value.trim();if(!name.includes('*')&&name.length>1)name=name[0]+'*'+(name.length>2?name.slice(-1):'');let m=$('month').value.split('-');text(`${m[0]||''}년 ${Number(m[1])||''}월 수강생 ${name}`,946,947,30,'#777',500,'right');x.fillStyle='#e6e6e8';x.fillRect(0,973,1080,107);text('서면 파고다',52,1039,32,'#777',900);text('|',260,1039,29,'#888',400);text('더쎈토익',314,1039,32,'#777',900);text('|',482,1039,29,'#888',400);text('부산 부산진구 신천대로62번길 58',620,1023,13,'#888',400,'center');text('(부산광역시 부산진구 부전동 232-9)',620,1042,13,'#888',400,'center');x.fillStyle='#ffdb00';x.fillRect(772,1005,276,47);text('Ch  더쎈토익 상담톡 ⊕',910,1037,24,'#171717',900,'center')}
document.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{draw()}));document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{course=b.dataset.class;document.querySelectorAll('[data-class]').forEach(t=>t.classList.toggle('active',t===b));draw()});
async function load(file){if(!file||busy)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>20*1024*1024){$('status').textContent='20MB 이하의 JPG, PNG, WEBP 이미지를 선택해 주세요.';return}busy=true;let url=URL.createObjectURL(file);try{uploaded=await new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=url});$('evidence').options[1].disabled=false;draw();$('status').textContent='점수를 읽는 중입니다. 잠시 기다려 주세요…';if(!window.Tesseract)throw Error('OCR');let result=await Tesseract.recognize(file,'eng');let t=result.data.text;let lc=t.match(/\bLC\s*[:：]?\s*(\d{2,3})/i),rc=t.match(/\bRC\s*[:：]?\s*(\d{2,3})/i),total=t.match(/(?:total|총점)\s*[:：]?\s*(\d{2,3})/i);let valid=(n,max)=>n&&Number(n[1])<=max&&Number(n[1])%5===0;if(valid(total,990))$('score').value=total[1];else if(valid(lc,495)&&valid(rc,495))$('score').value=Number(lc[1])+Number(rc[1]);$('status').textContent=(valid(total,990)||(valid(lc,495)&&valid(rc,495)))?'총점을 반영했습니다. 달성 점수를 확인해 주세요.':'점수를 확실히 읽지 못했습니다. 아래 점수를 직접 입력해 주세요.';draw()}catch(e){$('status').textContent='자동 인식을 완료하지 못했습니다. 아래에서 점수를 직접 입력할 수 있습니다.'}finally{busy=false;URL.revokeObjectURL(url)}}
$('file').onchange=e=>load(e.target.files[0]);let drop=document.querySelector('.drop');drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#ed242b'};drop.ondragleave=()=>drop.style.borderColor='';drop.ondrop=e=>{e.preventDefault();drop.style.borderColor='';load(e.dataTransfer.files[0])};$('save').onclick=()=>{draw();c.toBlob(blob=>{if(!blob)return;let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`더쎈토익_${course}_${$('score').value}점.png`;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)},'image/png')};$('evidence').options[1].disabled=true;draw();document.fonts.ready.then(draw);
